check("script review: short, echoing or bare scripts get one revision pass; near enough is left alone", () => {
  const settings = reupJobSettings("A", reupPresetDefaults("A"));
  const words = (n: number, tag = "w") => Array.from({ length: n }, (_x, i) => `${tag}${i}`).join(" ");
  const sec = (id: string, role: ReupSectionRole, text: string, value?: "why") => ({ id, role, text, shots: [], cues: [{ segment: "s1", text, ...(value ? { value } : {}) }] });
  const out = (sections: ReupSection[], id = "o1"): ReupOutputScript => ({ id, lang: "en", title: [], sections });
  const input = { settings, past: [] as string[] };
  assert.ok(!reupNeedsRevision(reupScriptReview({ outputs: [out([sec("h", "hook", words(100)), sec("a", "body", words(400), "why"), sec("b", "body", words(400), "why")])] }, input)));
  assert.ok(!reupNeedsRevision(reupScriptReview({ outputs: [out([sec("a", "body", words(780), "why")])] }, input)), "780 of 850 words is near enough: no extra AI pass");
  const short = reupScriptReview({ outputs: [out([sec("h", "hook", words(50)), sec("a", "body", words(200), "why"), sec("b", "body", words(100)), sec("e", "ending", words(20))])] }, input);
  assert.deepEqual(short.short.map((x) => [x.have, x.need, x.sections]), [[370, 850, [2, 3, 4]]], "lengthen body and ending sections, never the hook");
  assert.deepEqual(short.bare, [{ output: "o1", sections: [3] }]);
  assert.ok(reupNeedsRevision(short));
  const past = "He notches each log end so the walls lock together without nails. The roof goes on before the rain comes back again. A cabin like this one can stand for a whole century.";
  const echo = reupScriptReview({ outputs: [out([sec("a", "body", `${words(820)}. He notches each log end so the walls lock together tightly. The roof goes on before the rain comes back again. A cabin like this one can stand for a whole century or more.`, "why")])] }, { settings, past: [past] });
  assert.equal(echo.repeats[0].sentences.length, 3);
  assert.ok(reupNeedsRevision(echo) && !echo.short.length, "three sentences echoing earlier videos trigger a rewrite");
  assert.ok(reupIssueScore(short) > reupIssueScore({ short: [], repeats: [], bare: [], long: [], similar: 0 }));
  const phrases = reupPastText([{ outputs: [out([sec("a", "body", "Here we go. Notice how the walls lock together here. That is all.")])] }, { outputs: [out([sec("a", "body", "Morning comes. Again the walls lock together nicely. See you soon.")])] }], "en");
  assert.deepEqual([phrases.openings, phrases.closings], [["Here we go.", "Morning comes."], ["That is all.", "See you soon."]]);
  assert.ok(phrases.phrases.includes("the walls lock together"), phrases.phrases.join("; "));
});
check("fill: unused scenes from the whole source before any repeat; before/after kept apart; never far ahead; pauses shortened first", () => {
  const seg = (id: string, start: number, end: number, tags: string[] = [], value = 2) => ({ id, start, end, what: "", tags, value });
  const segs = [seg("s1", 0, 20, ["before"]), seg("s2", 20, 30), seg("s3", 30, 40), seg("s4", 40, 100, ["before"], 5), seg("s5", 100, 200, ["after"], 5), seg("s6", 200, 600, [], 5)];
  assert.deepEqual(reupFillScenes(segs, ["s2"], { stage: true }).map((f) => f.start), [30, 0, 40, 100], "neighbours first, then the nearest unused scene; nothing past 90 s ahead");
  assert.ok(!reupFillScenes(segs, ["s1"], { stage: true }).some((f) => f.start === 100), "a 'before' part never borrows 'after' footage");
  assert.ok(reupFillScenes(segs, ["s2"], { hook: true }).some((f) => f.start === 200), "the hook may borrow from anywhere");
  const many = [seg("a", 0, 10), seg("b", 10, 20), seg("c", 20, 30), seg("d", 30, 40), seg("e", 40, 200)];
  const opts = { duration: 200, bad: [], minShot: 1.6, maxShot: 7, hookCut: 1.2, guard: 2 };
  const near = new ReupFootageLedger(opts).plan([{ start: 0, end: 10 }], 60, false, reupNearScenes(many, ["a"]), true);
  const wide = new ReupFootageLedger(opts).plan([{ start: 0, end: 10 }], 60, false, reupFillScenes(many, ["a"]), true);
  assert.ok(near.repeated && !wide.repeated && wide.scenes >= 3, `two neighbours run dry; the whole source does not (${wide.scenes} scenes)`);
  const shrunk = new ReupFootageLedger(opts).plan([{ start: 0, end: 10 }], 20, false, [], true, 15);
  assert.ok(!shrunk.repeated && shrunk.shrunk > 10 && shrunk.seconds < 10, "a silent tail is shortened instead of repeating a shot");
  assert.ok(new ReupFootageLedger(opts).plan([{ start: 0, end: 10 }], 20, false, [], true, 5).repeated, "speech is never cut: past the tail it still repeats");
});
check("advice and reuse: length warning per type, reuse counts finished runs only, folders match by their files", () => {
  const advice = (id: ReupPresetId, usable: number, extra: Partial<ReupSettings> = {}) => reupLengthAdvice(reupPreset(id), { ...reupPresetDefaults(id), ...extra }, usable);
  assert.equal(advice("A", 1000), undefined);
  assert.deepEqual(advice("A", 1000, { targetSeconds: 900 }), { need: 900, usable: 1000, suggest: 600 }, "15 minutes from a 16-minute source: suggest 10");
  assert.deepEqual(advice("A", 100, { targetSeconds: 120 }), { need: 120, usable: 100, suggest: 60 }, "a short video from a short source: suggest 1 minute");
  assert.deepEqual(advice("D", 150), { need: 180, usable: 150, suggest: 120 }, "photo report: as long as the photos last");
  const items = (names: string[]) => names.map((name, i) => ({ id: `m${i}`, path: name, name, type: "photo" as const, start: i * 5, end: i * 5 + 5, width: 4, height: 3, hasAudio: false }));
  const folder = (names: string[], fingerprint = "f") => ({ fingerprint, source: { kind: "folder", items: items(names) } as ReupSource });
  const ten = Array.from({ length: 10 }, (_x, i) => `p${i}.jpg`);
  assert.ok(reupSameSource(folder(ten, "a"), folder([...ten.slice(0, 8), "x.jpg"], "b")), "8 of 10 photos again is the same report");
  assert.ok(!reupSameSource(folder(ten, "a"), folder(ten.slice(0, 5), "b")));
  const video = { fingerprint: "v", source: { kind: "video" } as ReupSource };
  assert.equal(reupSourceReuses(video, [{ ...video, outputs: [] }, { ...video, outputs: [{} as ReupOutputResult] }]), 1, "a cancelled run is not a published video");
});
