check("builder's talk (H): kept lines lower the words needed, are marked for the writer and count as voice", () => {
  assert.ok(reupPresetRules("H").keepTalk && !reupPresetRules("A").keepTalk && !reupPresetRules("G").keepTalk);
  const phrase = (start: number, end: number, text: string) => ({ id: `p${start}`, from: 0, to: 0, start, end, text });
  const talk = reupTalkPhrases([phrase(10, 13, "this bracket holds the axle"), phrase(40, 41, "okay"), phrase(80, 95, "now we weld the frame rail on both sides carefully")]);
  assert.equal(talk.length, 2, "one-word grunts are not lines");
  const share = reupTalkShare(talk, 540);
  assert.ok(share > 0 && share <= 0.1);
  const settings = reupJobSettings("H", reupPresetDefaults("H"));
  assert.ok(reupWordBudget(settings, "en", { talk: 0.1 }).min < reupWordBudget(settings, "en").min, "the channel writes less where the builder talks");
  assert.equal(reupTalkTail(talk, { start: 0, end: 30 }, 5, 9.5), 8.3, "a line starting right after the voice ends extends the cue to its end");
  assert.equal(reupTalkTail(talk, { start: 0, end: 30 }, 5, 4), undefined, "a line far after the voice is not waited for");
  assert.equal(reupHeardTalk(talk, [{ seek: 5, len: 10 }], 4), 3, "heard only after the voice stops");
  assert.equal(reupHeardTalk(talk, [{ seek: 5, len: 10 }], 7), 0, "a line mostly under the voice does not count");
  const map = { summary: "", hook: [], ending: "", thumbnails: [], segments: [{ id: "s1", start: 0, end: 30, what: "frame", tags: [], value: 3, moments: [{ id: "s1m1", t: 0, what: "measure", pull: 3 }, { id: "s1m2", t: 10, what: "bracket", pull: 4 }] }] };
  const prompt = REUP_PROMPT.SCRIPT({ map, settings, rules: "", duration: 30, style: pickReupStyle(reupPresetRules("H"), [], "h"), budget: reupWordBudget(settings, "en"), marks: 0, talk });
  assert.match(prompt, /s1m2 0:10 .*🗣"this bracket holds the axle…"/);
  assert.match(prompt, /Do not talk over them/);
  const base = { id: "now", createdAt: 2, updatedAt: 2, preset: "H", settings, rights: "own", source: {} as any, status: "done", steps: {}, logs: [], sheets: [], bad: [], warnings: [] } as unknown as ReupJob;
  const out = { id: "o1", file: "", url: "", duration: 100, width: 1, height: 1, narrated: 66, voiced: 66 };
  assert.ok(reupReport({ ...base, outputs: [out] }, []).notes.some((n) => n.code === "coverage"));
  assert.ok(!reupReport({ ...base, outputs: [{ ...out, talk: 8 }] }, []).notes.some((n) => n.code === "coverage"), "the builder's kept lines count toward voice coverage");
});
