check("fixed corner text in the source is found and cropped off thumbnail frames", () => {
  const w = 160,
    h = 90,
    n = 60;
  const make = (marked: boolean): Uint8Array => {
    const raw = new Uint8Array(w * h * n);
    let seed = 7;
    const rnd = () => ((seed = (Math.imul(seed, 1103515245) + 12345) >>> 0) / 2 ** 32);
    const blocks = _.range(n).map(() => _.range(60).map(() => 40 + 160 * rnd()));
    for (let f = 0; f < n; f++)
      for (let y = 0; y < h; y++)
        for (let x = 0; x < w; x++) {
          const mark = marked && y >= 3 && y <= 6 && x >= 120 && x <= 150 && x % 3 === 0 ? 14 : 0;
          raw[(f * h + y) * w + x] = Math.min(255, blocks[f][(y >> 4) * 10 + (x >> 4)] + 20 * rnd() + mark);
        }
    return raw;
  };
  assert.equal(reupWatermarkCorner(make(true), w, h), "tr", "faint fixed text in the top right corner");
  assert.equal(reupWatermarkCorner(make(false), w, h), undefined, "changing footage alone is not a watermark");
  assert.equal(reupWatermarkCrop("tr"), "crop=iw*0.88:ih*0.88:0:ih*0.12,");
  assert.equal(reupWatermarkCrop(undefined), "");
});
